r %1: %2\",name _unit,_loadout]; \n}] call compile_Global; Type: Server','2025-11-11 14:01:33'),(21929,'Matthew Evans (Madi Moore)','76561198147147468','DebugExecuted','Debug: [\"Server_Gear_Save\", { \n params [ \n  [\"_unit\",objNull,[objNull]], \n  [\"_delete\",false,[false]] \n ]; \n diag_log format[\"[DEBUG] Saving gear for %1 | Delete: %2\",name _unit,_delete]; \n private _loadout = [_unit] call A3PL_Lib_Loadout; \n diag_log format[\"[DEBUG] Loadout: %1\",_loadout]; \n private _pos = getPosATL _unit; \n \n if (_delete) then {deleteVehicle _unit;}; \n \n private _charid = _unit getVariable [\"character_id\",0]; \n \n private _job = _unit getVariable [\"job\",localize\"STR_Common_Job_Unemployed\"]; \n private _virtinv = _unit getVariable [\"player_inventory\",[]]; \n private _ship = [_unit getVariable [\"player_importing\",[]],_unit getVariable [\"player_exporting\",[]]]; \n private _medWounds = _unit getVariable [\"A3PL_Wounds\",[]]; \n private _blood = _unit getVariable [\"A3PL_Medical_Blood\",5000]; \n private _medStat = [_medWounds,_blood]; \n private _hunger = _unit getVariable [\"player_hunger\",0]; \n private _thirst = _unit getVariable [\"player_thirst\",0]; \n private _alcohol = _unit getVariable [\"player_alcohol\",0]; \n private _drugs = _unit getVariable [\"player_drugs\",[0,0,0]]; \n private _pee = _unit getVariable [\"player_pee\",0]; \n private _sleep = _unit getVariable [\"player_sleep\",0]; \n private _stats = [_hunger,_thirst,_alcohol,_drugs,_pee,_sleep]; \n private _sportLevel = _unit getVariable [\"Player_SportLevel\",0]; \n private _sportSpeed = _unit getVariable [\"Player_SportSpeed\",0]; \n private _scopeStability = _unit getVariable [\"Player_ScopeStability\",0]; \n private _maxTimeTired = _unit getVariable [\"Player_maxTimeTired\",0]; \n private _sport = [_sportLevel,_sportSpeed,_scopeStability,_maxTimeTired]; \n private _cash = _unit getVariable \"Player_Cash\"; \n private _bank = _unit getVariable [\"Player_Bank\",0]; \n private _bankActive = _unit getVariable [\"Player_BankActive\",false]; \n if (_bankActive) then { \n  _bankActive = 1; \n } else { \n  _bankActive = 0; \n }; \n private _Savings = _unit getVariable [\"Player_SavingsAccount\",0]; \n private _SavingsActive = _unit getVariable [\"Player_SavingsAccountActive\",false]; \n if (_SavingsActive) then { \n  _SavingsActive = 1; \n } else { \n  _SavingsActive = 0; \n }; \n private _COD = _unit getVariable [\"Player_CertificateOfDeposit\",0]; \n private _CODActive = _unit getVariable [\"Player_CertificateOfDepositActive\",false]; \n if (_CODActive) then { \n  _CODActive = 1; \n } else { \n  _CODActive = 0; \n }; \n private _activecb = _unit getVariable \"Player_ActiveCB\"; \n private _debt = _unit getVariable \"Player_Debt\"; \n private _limitCB = _unit getVariable \"Player_LimitCB\"; \n \n if (_pos inArea \"A3FL_DebugSpawn\") exitwith {}; \n if (isNil \"_cash\") exitwith {diag_log format [\"Error in Server_Gear_Save: _cash is nil for %1\",name _unit];}; \n \n private _query = format [\"UPDATE players SET loadout=%2,position=%3,job=%4,virtualinv=%5,cash=%6,medstats=%7,ship=%8,bank=%9,bankactive=%10,savingsaccount=%11,savingsaccountactive=%12,certificateofdeposit=%13,certificateofdepositactive=%14,activecb=%15,debt=%16,limitcb=%17,stats=%18,sport=%19 WHERE charid =%1\", \n  _charid, \n  [_loadout] call Server_Database_Array, \n  _pos, \n  _job, \n  [_virtinv] call Server_Database_Array, \n  _cash, \n  _medStat, \n  [_ship] call Server_Database_Array, \n  _bank, \n  _bankActive, \n  _Savings, \n  _SavingsActive, \n  _COD, \n  _CODActive, \n  _activecb, \n  _debt, \n  _limitcb, \n  _stats, \n  _sport \n ]; \n [_query,1] spawn Server_Database_Async; \n}] call compile_Server; Type: Server','2025-11-11 14:01:46'),(21930,'Matthew Evans (Madi Moore)','76561198147147468','DebugExecuted','Debug: [\"A3PL_Lib_Loadout\", \n{ \n params [\"_unit\"]; \n diag_log format[\"[DEBUG] Fetching gear for %1\",name _unit]; \n private _loadout = getUnitLoadout _unit; \n diag_log format[\"[DEBUG] Basic loadout: %1\",_loadout]; \n private _specialItems = _loadout#9; \n diag_log format[\"[DEBUG] SpecialItems for %1: %2\",name _unit,_specialItems]; \n private _radio = _specialItems#2; \n diag_log format[\"[DEBUG] radio for %1: %2\",name _unit,_radio]; \n if(_radio isEqualTo \"\") exitwith {diag_log \"[DEBUG] No radio found in loadout, exiting with basic loadout.\"; _loadout; }; \n private _radioClass = configFile >> \"CfgWeapons\" >> _radio; \n if ((isClass _radioClass) && {isNumber (_radioClass >> \"tf_radio\")}) then { \n  diag_log format[\"[DEBUG] Radio found, updating loadout for %1\",name _unit]; \n  _specialItems set[2, getText(_radioClass >> \"tf_parent\")]; \n  diag_log format[\"[DEBUG] New specialItems for %1: %2\",name _unit,_specialItems]; \n  _loadout set[9, _specialItems]; \n  diag_log format[\"[DEBUG] New loadout for %1: %2\",name _unit,_loadout]; \n }; \n diag_log format[\"[DEBUG] Final loadout for %1: %2\",name _unit,_loadout]; \n _loadout; \n}] call compile_Global; Type: Server','2025-11-11 14:15:45'),(21931,'Matthew Evans (Madi Moore)','76561198147147468','DebugExecuted','Debug: { \n    diag_log format[\"[DEBUG] Spawning Server_Gear_Save for %1 at %2\", name _x, time]; \n    [_x,false] spawn Server_Gear_Save; \n    sleep 10; \n   } foreach allPlayers; Type: Server','2025-11-11 14:17:11');
